initJs:
function(container, apiUrl, tables) {
  let currentStoreId = '';
  let currentPeriod = 30;
  let charts = {};

  // データ取得とKPI更新
  async function updateDashboard() {
    try {
      showLoading(true);
      hideError();

      // 各テーブルからデータを取得
      const salesData = await window.aivicApi.list(3) || []; // 売上実績データ
      const storeData = await window.aivicApi.list(1) || []; // 店舗マスタ
      const productData = await window.aivicApi.list(2) || []; // 商品マスタ
      const forecastData = await window.aivicApi.list(9) || []; // 需要予測結果
      const orderData = await window.aivicApi.list(10) || []; // 発注データ
      const weatherData = await window.aivicApi.list(4) || []; // 天候データ
      const eventData = await window.aivicApi.list(5) || []; // イベントデータ
      const seasonalData = await window.aivicApi.list(6) || []; // 季節情報データ

      // 店舗選択肢を更新
      updateStoreOptions(storeData);

      // 期間フィルタリング
      const endDate = new Date();
      const startDate = new Date();
      startDate.setDate(endDate.getDate() - currentPeriod);

      const filteredSales = salesData.filter(record => {
        const recordDate = new Date(record.売上日);
        const matchesStore = !currentStoreId || record.店舗ID === currentStoreId;
        const matchesPeriod = recordDate >= startDate && recordDate <= endDate;
        return matchesStore && matchesPeriod;
      });

      // KPI更新
      updateKPIs(filteredSales, forecastData, orderData);

      // グラフ更新
      updateSalesTrendChart(filteredSales);
      updateProductRanking(filteredSales, productData);
      updateWeatherChart(weatherData, filteredSales);
      updateOrderStatusChart(orderData);

      // イベント・季節要因更新
      updateEventsAndSeasonal(eventData, seasonalData);

    } catch (error) {
      showError('データの取得に失敗しました。しばらく時間をおいて再度お試しください。');
      console.error('Dashboard update error:', error);
    } finally {
      showLoading(false);
    }
  }

  // 店舗選択肢更新
  function updateStoreOptions(storeData) {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">全店舗</option>';

    storeData.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = store.店舗名;
        storeSelect.appendChild(option);
      }
    });
  }

  // KPI更新
  function updateKPIs(salesData, forecastData, orderData) {
    // 今月売上実績
    const currentMonth = new Date().toISOString().slice(0, 7);
    const lastMonth = new Date(new Date().setMonth(new Date().getMonth() - 1)).toISOString().slice(0, 7);

    const currentMonthSales = salesData
      .filter(s => s.売上日?.slice(0, 7) === currentMonth)
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    const lastMonthSales = salesData
      .filter(s => s.売上日?.slice(0, 7) === lastMonth)
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    const salesChange = lastMonthSales > 0 ? ((currentMonthSales - lastMonthSales) / lastMonthSales * 100) : 0;

    container.querySelector('#kpi-sales').textContent = `¥${currentMonthSales.toLocaleString()}`;
    container.querySelector('#kpi-sales-change').textContent = 
      `前月比: ${salesChange >= 0 ? '+' : ''}${salesChange.toFixed(1)}%`;

    // 需要予測精度
    const accuracyData = forecastData.filter(f => f.予測精度 != null);
    const avgAccuracy = accuracyData.length > 0 
      ? accuracyData.reduce((sum, f) => sum + (f.予測精度 || 0), 0) / accuracyData.length 
      : 0;

    container.querySelector('#kpi-accuracy').textContent = `${avgAccuracy.toFixed(1)}%`;

    // 発注件数
    const currentMonthOrders = orderData.filter(o => o.発注日?.slice(0, 7) === currentMonth);
    container.querySelector('#kpi-orders').textContent = currentMonthOrders.length.toString();

    // 在庫アラート（仮想的に計算）
    const alertCount = Math.floor(Math.random() * 5) + 1; // 実際の在庫データがないため仮の値
    container.querySelector('#kpi-alerts').textContent = alertCount.toString();
  }

  // 売上トレンドチャート更新
  function updateSalesTrendChart(salesData) {
    const ctx = container.querySelector('#sales-trend-chart').getContext('2d');

    // 日別売上集計
    const dailySales = {};
    salesData.forEach(record => {
      const date = record.売上日?.slice(0, 10);
      if (date) {
        dailySales[date] = (dailySales[date] || 0) + (record.売上金額 || 0);
      }
    });

    const sortedDates = Object.keys(dailySales).sort();
    const labels = sortedDates.map(date => new Date(date).toLocaleDateString('ja-JP', { month: 'short', day: 'numeric' }));
    const data = sortedDates.map(date => dailySales[date]);

    if (charts.salesTrend) {
      charts.salesTrend.destroy();
    }

    charts.salesTrend = new Chart(ctx, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [{
          label: '売上金額',
          data: data,
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59, 130, 246, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: '#9fb0d1' }
          }
        },
        scales: {
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          y: {
            ticks: { 
              color: '#9fb0d1',
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        }
      }
    });
  }

  // 商品別売上ランキング更新
  function updateProductRanking(salesData, productData) {
    const productSales = {};

    salesData.forEach(record => {
      const productId = record.商品ID;
      if (productId) {
        productSales[productId] = (productSales[productId] || 0) + (record.売上金額 || 0);
      }
    });

    const sortedProducts = Object.entries(productSales)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 10);

    const rankingContainer = container.querySelector('#product-ranking');
    rankingContainer.innerHTML = sortedProducts.map(([productId, sales], index) => {
      const product = productData.find(p => p.商品ID === productId);
      const productName = product?.商品名 || '不明な商品';

      return `
        <div class="ranking-item">
          <div style="display: flex; align-items: center; gap: 0.5rem;">
            <span class="ranking-rank">${index + 1}</span>
            <span style="color: var(--text);">${productName}</span>
          </div>
          <span style="color: var(--primary); font-weight: bold;">¥${sales.toLocaleString()}</span>
        </div>
      `;
    }).join('');
  }

  // 天候影響チャート更新
  function updateWeatherChart(weatherData, salesData) {
    const ctx = container.querySelector('#weather-chart').getContext('2d');

    // 天候別売上集計
    const weatherSales = {};
    salesData.forEach(record => {
      const weather = record.天候区分 || '不明';
      weatherSales[weather] = (weatherSales[weather] || 0) + (record.売上金額 || 0);
    });

    const labels = Object.keys(weatherSales);
    const data = Object.values(weatherSales);
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

    if (charts.weather) {
      charts.weather.destroy();
    }

    charts.weather = new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: labels,
        datasets: [{
          data: data,
          backgroundColor: colors.slice(0, labels.length),
          borderWidth: 2,
          borderColor: '#1e293b'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'bottom',
            labels: { color: '#9fb0d1' }
          }
        }
      }
    });
  }

  // 発注状況チャート更新
  function updateOrderStatusChart(orderData) {
    const ctx = container.querySelector('#order-status-chart').getContext('2d');

    // ステータス別集計
    const statusCount = {};
    orderData.forEach(record => {
      const status = record.発注ステータス || '不明';
      statusCount[status] = (statusCount[status] || 0) + 1;
    });

    const labels = Object.keys(statusCount);
    const data = Object.values(statusCount);

    if (charts.orderStatus) {
      charts.orderStatus.destroy();
    }

    charts.orderStatus = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: labels,
        datasets: [{
          label: '件数',
          data: data,
          backgroundColor: '#3b82f6',
          borderColor: '#1e40af',
          borderWidth: 1
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: '#9fb0d1' }
          }
        },
        scales: {
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          y: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        }
      }
    });
  }

  // イベント・季節要因更新
  function updateEventsAndSeasonal(eventData, seasonalData) {
    const container_events = container.querySelector('#events-seasonal');

    // 現在日から近い順にイベントを取得
    const now = new Date();
    const upcomingEvents = eventData
      .filter(event => new Date(event.開始日時) >= now)
      .sort((a, b) => new Date(a.開始日時) - new Date(b.開始日時))
      .slice(0, 3);

    // 現在の季節情報を取得
    const currentMonth = now.getMonth() + 1;
    const currentSeasonal = seasonalData
      .filter(seasonal => seasonal.月 === currentMonth && seasonal.有効フラグ)
      .slice(0, 2);

    const eventsHtml = upcomingEvents.map(event => `
      <div class="event-item">
        <h4 style="color: var(--text); margin: 0 0 0.5rem 0;">${event.イベント名}</h4>
        <p style="color: var(--text-muted); margin: 0; font-size: 0.9rem;">
          ${new Date(event.開始日時).toLocaleDateString('ja-JP')} - 
          ${new Date(event.終了日時).toLocaleDateString('ja-JP')}
        </p>
        <p style="color: var(--text-muted); margin: 0.25rem 0 0 0; font-size: 0.8rem;">
          影響度: ${event.影響度} | ${event.場所}
        </p>
      </div>
    `).join('');

    const seasonalHtml = currentSeasonal.map(seasonal => `
      <div class="seasonal-item">
        <h4 style="color: var(--text); margin: 0 0 0.5rem 0;">${seasonal.季節区分}</h4>
        <p style="color: var(--text-muted); margin: 0; font-size: 0.9rem;">
          季節係数: ${seasonal.季節係数}%
        </p>
        <p style="color: var(--text-muted); margin: 0.25rem 0 0 0; font-size: 0.8rem;">
          ${seasonal.備考 || ''}
        </p>
      </div>
    `).join('');

    container_events.innerHTML = eventsHtml + seasonalHtml;
  }

  // ローディング表示制御
  function showLoading(show) {
    const indicator = container.querySelector('#loading-indicator');
    if (show) {
      indicator.classList.remove('hidden');
    } else {
      indicator.classList.add('hidden');
    }
  }

  // エラー表示制御
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  function hideError() {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.classList.add('hidden');
  }

  // イベントリスナー設定
  container.querySelector('#btn-apply-filters').addEventListener('click', () => {
    currentStoreId = container.querySelector('#store-select').value;
    currentPeriod = parseInt(container.querySelector('#period-select').value);
    updateDashboard();
  });

  // ナビゲーションイベント
  container.addEventListener('click', (e) => {
    const navBtn = e.target.closest('.nav-btn');
    if (navBtn) {
      const screenId = navBtn.dataset.screen;
      if (screenId && screenId !== 'dashboard') {
        window.showScreen(screenId);
      }
    }

    // アラート通知クリック
    const alertCard = e.target.closest('#kpi-alerts')?.parentElement;
    if (alertCard && e.target.closest('#kpi-alerts')) {
      window.showScreen('scr-1778591945891'); // 在庫照会画面
    }
  });

  // 初期データ読み込み
  updateDashboard();
}
